def parse_duration(s):
    total_seconds = 0
    current_number = ""
    for char in s:
        if char.isdigit():
            current_number += char
        elif char == 'h':
            if current_number:
                total_seconds += int(current_number) * 3600
                current_number = ""
        elif char == 'm':
            if current_number:
                total_seconds += int(current_number) * 60
                current_number = ""
        elif char == 's':
            if current_number:
                total_seconds += int(current_number)
                current_number = ""
    return total_seconds
